local folder = game.ServerStorage:FindFirstChild("Animations") or Instance.new("Folder")
folder.Name = "Animations"; folder.Parent = game.ServerStorage
local old = folder:FindFirstChild(seq.Name)
if old then old:Destroy() end
seq.Parent = folder
local ok, id = pcall(function() return game:GetService("AnimationClipProvider"):RegisterAnimationClip(seq) end)
local previewId = ok and tostring(id) or nil
seq:SetAttribute("PreviewId", previewId)
return string.format("built %s (%d keyframes); preview id: %s", seq:GetFullName(), #seq:GetKeyframes(), tostring(previewId))
